{
  "findings": [
    {
      "ref": "[D533]",
      "area": "age_gating",
      "claim": "A parent reports that Minecraft has no age gate in practice, and the game is played by children of all ages.",
      "stance": "neutral",
      "quote": "Minecraft’s own parents’ guide notes that the game has players of all ages."
    },
    {
      "ref": "[D533]",
      "area": "contact",
      "claim": "A parent reports that online play is switched off by default on child accounts in Minecraft.",
      "stance": "mitigation",
      "quote": "Multiplayer is off by default on child accounts in both Java Edition and Bedrock Edition."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "A parent reports that Minecraft includes in-game purchases through the Marketplace and Realms subscriptions.",
      "stance": "risk",
      "quote": "Bedrock Edition’s Marketplace sells maps, skins and mini-games for Minecoins, an in-game currency bought with real money. Minecraft says Marketplace content is curated for quality and safety."
    },
    {
      "ref": "[D533]",
      "area": "data",
      "claim": "A parent reports that Minecraft requires a Microsoft account and that older versions miss safety features.",
      "stance": "neutral",
      "quote": "Minecraft’s controls live in your child’s Microsoft account, not inside the game. Bedrock Edition, Java Edition and Realms all require a Microsoft account, even if your child doesn’t play on an Xbox."
    },
    {
      "ref": "[D533]",
      "area": "content",
      "claim": "A parent reports that Minecraft contains mild cartoonish violence with monsters like zombies and skeletons, but no blood and players respawn after losing health.",
      "stance": "neutral",
      "quote": "Violence is mild and cartoonish. Players fight monsters such as zombies and skeletons with swords, axes and bows. They can also hurt animals and villagers, though the game doesn’t encourage it."
    },
    {
      "ref": "[D533]",
      "area": "contact",
      "claim": "A parent reports that chat on servers is where most risk lives, and players can block, mute or report others from the pause menu.",
      "stance": "mitigation",
      "quote": "Chat on those servers is where most of the risk lives. Both versions let players block, mute or report someone from the pause menu, and Java Edition has a Player Reporting tool that sends abusive chat to Minecraft’s moderators, including from private servers."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "A parent reports that the App Store lists Realms subscriptions that host a private world for invited friends.",
      "stance": "neutral",
      "quote": "The App Store also lists Realms subscriptions, which host a private world for invited friends."
    },
    {
      "ref": "[D533]",
      "area": "data",
      "claim": "A parent reports that parental controls do not work on Minecraft versions older than 1.16.4 or on modded versions.",
      "stance": "risk",
      "quote": "Parental controls don’t work on Minecraft versions older than 1.16.4 or on modded versions."
    },
    {
      "ref": "[D533]",
      "area": "age_gating",
      "claim": "A parent reports that Microsoft is starting to ask some account holders to verify their age, but the United States is not listed as of October 2026.",
      "stance": "neutral",
      "quote": "Microsoft, which owns Minecraft, has started asking some account holders to verify their age. Its age assurance FAQ says users in the United Kingdom, Australia, Brazil and Singapore can verify now, with a selfie-based age estimate, an ID document or a government login."
    }
  ]
}
